const MODEL_YEAR_BY_PATH = new Map(PRICE_HISTORY_MODEL_YEAR_SEO_PAGES.map((item) => [item.path, item]));

export function normalizePriceHistoryModelYearPath(pathname) {
  const value = String(pathname || "").trim();
  if (!value) return "/";
  const withoutQuery = value.split("?")[0].split("#")[0];
  const normalized = withoutQuery.length > 1 ? withoutQuery.replace(/\/+$/, "") : withoutQuery;
  return normalized || "/";
}

export function getPriceHistoryModelYearSeo(pathname) {
  return MODEL_YEAR_BY_PATH.get(normalizePriceHistoryModelYearPath(pathname)) || null;
}

export function isPriceHistoryModelYearSeoEligiblePath(pathname) {
  return Boolean(getPriceHistoryModelYearSeo(pathname));
}
